import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { checkout } from './src/app.js';
import { makeReceiptKey as billingKey } from './src/billing/receipt.js';
import { makeReceiptKey as reportKey } from './src/reports/receipt.js';
import { makeReceiptKey as transportKey } from './src/transport/receipt.js';

const answer = JSON.parse(await readFile('answer.json', 'utf8'));
assert.deepEqual(Object.keys(answer).sort(), ['call_chain', 'example_key', 'outbound_file', 'outbound_symbol', 'owner_file', 'owner_symbol']);
assert.equal(answer.owner_file, 'src/billing/receipt.js');
assert.equal(answer.owner_symbol, 'makeReceiptKey');
assert.equal(answer.outbound_file, 'src/transport/invoices.js');
assert.equal(answer.outbound_symbol, 'sendInvoice');
assert.deepEqual(answer.call_chain.map(({ file, symbol }) => [file, symbol]), [
  ['src/app.js', 'checkout'],
  ['src/billing/submit.js', 'submitInvoice'],
  ['src/transport/invoices.js', 'sendInvoice']
]);
assert.equal(answer.call_chain[1].key_from, 'src/billing/receipt.js:makeReceiptKey');
const invoice = { accountId: 'acme', sequence: 7 };
let posted;
const provider = { post: async (...args) => { posted = args; return 'sent'; } };
assert.equal(await checkout(invoice, provider), 'sent');
assert.equal(billingKey(invoice), 'invoice/acme/0007');
assert.equal(answer.example_key, billingKey(invoice));
assert.deepEqual(posted, ['/invoices', invoice, { 'Idempotency-Key': answer.example_key }]);
assert.equal(reportKey({ id: 7 }), 'report:7');
assert.equal(transportKey({ headers: { 'x-receipt': 'received' } }), 'received');
console.log('PASS: answer structure, checkout header, example key, and distinct receipt helpers');
